"""Tests for the OpenQASM 2.0 export."""

from __future__ import annotations

import math

import pytest

import vqubit


def test_simple_circuit() -> None:
	q0, q1 = vqubit.LineQubit.range(2)
	circuit = vqubit.Circuit(vqubit.H(q0), vqubit.CNOT(q0, q1))
	assert vqubit.qasm(circuit) == "\n".join(
		[
			"// Generated by vqubit",
			"OPENQASM 2.0;",
			'include "qelib1.inc";',
			"qreg q[2];",
			"h q[0];",
			"cx q[0],q[1];",
		]
	)


def test_measurement_registers() -> None:
	# The key is the classical register, verbatim, so that importing the text
	# back gives the same key (the importer is the other half of the round trip).
	q0, q1 = vqubit.LineQubit.range(2)
	circuit = vqubit.Circuit(vqubit.measure(q0, q1, key="m"))
	text = vqubit.qasm(circuit)
	assert "creg m[2];" in text
	assert "measure q[0] -> m[0];" in text
	assert "measure q[1] -> m[1];" in text
	with pytest.raises(ValueError):
		vqubit.qasm(vqubit.Circuit(vqubit.measure(q0, key="not an identifier")))


def test_rotation_with_angle() -> None:
	q0 = vqubit.LineQubit(0)
	text = vqubit.qasm(vqubit.Rx(math.pi)(q0))
	assert text == "rx(3.141592653589793) q[0];"


def test_single_qubit_gates() -> None:
	q0 = vqubit.LineQubit(0)
	assert vqubit.qasm(vqubit.X(q0)) == "x q[0];"
	assert vqubit.qasm(vqubit.S(q0)) == "s q[0];"
	assert vqubit.qasm(vqubit.T(q0)) == "t q[0];"
	assert vqubit.qasm((vqubit.S**-1).on(q0)) == "sdg q[0];"


def test_two_qubit_gates() -> None:
	q0, q1 = vqubit.LineQubit.range(2)
	assert vqubit.qasm(vqubit.CZ(q0, q1)) == "cz q[0],q[1];"
	assert vqubit.qasm(vqubit.SWAP(q0, q1)) == "swap q[0],q[1];"


def test_ccx_uses_the_native_instruction() -> None:
	q0, q1, q2 = vqubit.LineQubit.range(3)
	assert vqubit.qasm(vqubit.CCX(q0, q1, q2)) == "ccx q[0],q[1],q[2];"


def test_cswap_is_decomposed() -> None:
	q0, q1, q2 = vqubit.LineQubit.range(3)
	lines = vqubit.qasm(vqubit.CSWAP(q0, q1, q2)).splitlines()
	assert lines[0] == "cx q[2],q[1];"
	assert lines[-1] == "cx q[2],q[1];"
	assert any(line.startswith("ccx ") for line in lines)


def test_unsupported_gate_raises() -> None:
	q0, q1 = vqubit.LineQubit.range(2)
	with pytest.raises(TypeError):
		vqubit.qasm(vqubit.ISWAP(q0, q1))
